SELECT PetType, MAX(weight) AS max_weight
FROM Pets
GROUP BY PetType;

SELECT S.Fname, S.Age
FROM Student S
WHERE S.StuID IN (SELECT StuID FROM Has_Pet);

SELECT StuID, COUNT(PetID) AS NumberOfPets
FROM Has_Pet
GROUP BY StuID;

SELECT car_makers.Maker, model_list.Model
FROM car_makers
JOIN model_list ON car_makers.Id = model_list.Maker;

SELECT loser_name, winner_name
FROM matches
WHERE minutes = (SELECT MAX(minutes) FROM matches);

SELECT MAX(Share) AS max_share, MIN(Share) AS min_share
FROM performance
WHERE Type <> 'Live final';

SELECT Record_Company, COUNT(Orchestra_ID) AS Number_of_Orchestras
FROM orchestra
GROUP BY Record_Company;

SELECT T.cost_of_treatment, TT.treatment_type_description
FROM Treatments T
JOIN Treatment_Types TT ON T.treatment_type_code = TT.treatment_type_code;

SELECT Citizenship FROM singer WHERE Birth_Year < 1945
INTERSECT
SELECT Citizenship FROM singer WHERE Birth_Year > 1955;

SELECT Ref_Property_Types.property_type_description
FROM Properties
JOIN Ref_Property_Types ON Properties.property_type_code = Ref_Property_Types.property_type_code;
